package com.adent.operations.api; import com.adent.shared.security.CurrentUser; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/operations/reports") public class OperationalReportController {private final CurrentUser current;private final JdbcTemplate jdbc;public OperationalReportController(CurrentUser c,JdbcTemplate j){current=c;jdbc=j;} @GetMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN','SECURITY','CLEANING')") public List<Map<String,Object>> list(@RequestParam String type){return jdbc.queryForList("select id,report_type,username,category,description,status,occurred_at from operational_reports where tenant_id=? and report_type=? order by occurred_at desc",current.tenantId(),type.toUpperCase());} @PostMapping @PreAuthorize("hasAnyRole('SECURITY','CLEANING')") public Map<String,Object> create(@RequestBody Request r){UUID id=UUID.randomUUID();String type=r.reportType().toUpperCase();if(!current.roles().contains(type)) throw new IllegalArgumentException("Tipo de reporte no permitido para este rol");OffsetDateTime at=r.occurredAt()==null?OffsetDateTime.now():r.occurredAt();jdbc.update("insert into operational_reports(id,tenant_id,report_type,username,category,description,status,occurred_at) values(?,?,?,?,?,?,?,?)",id,current.tenantId(),type,current.username(),r.category(),r.description(),"OPEN",at);return Map.of("id",id,"status","OPEN");} public record Request(String reportType,String category,String description,OffsetDateTime occurredAt){} }
